<template>
 <div><el-descriptions :column="2" border><el-descriptions-item label="状态">{{({COMPLETED:'评价完成',INCOMPLETE:'评价未完成'}[network?.status]||'未执行')}}</el-descriptions-item><el-descriptions-item label="评价方法">井间距法 + 分离系数法</el-descriptions-item><el-descriptions-item label="最小中心距">{{fmt(network?.min_distance??network?.minimum_distance)}} m</el-descriptions-item><el-descriptions-item label="最小 SF">{{fmt(network?.minimum_sf)}}</el-descriptions-item></el-descriptions>
 <el-collapse :model-value="['pairs','risks','failures','alarms']"><el-collapse-item title="井对关系" name="pairs"><el-table :data="pairs" border @current-change="selected=$event"><el-table-column label="邻井 / 井眼" min-width="120"><template #default="s">{{name(s.row)}}</template></el-table-column><el-table-column v-if="!network?.demo_case" prop="neighbor_survey_version_id" label="版本 ID" width="90"/><el-table-column label="中心距（m）" width="110"><template #default="s">{{fmt(s.row.min_distance)}}</template></el-table-column><el-table-column label="SF" width="85"><template #default="s">{{fmt(s.row.sf)}}</template></el-table-column><el-table-column label="风险" width="85"><template #default="s"><el-tag size="small" effect="plain" :style="riskStyle(s.row.risk_level)">{{riskName(s.row.risk_level)}}</el-tag></template></el-table-column></el-table><pagination v-if="(network?.results?.length||0)>10" v-model:page="page" v-model:limit="limit" :total="network.results.length"/></el-collapse-item>
 <el-collapse-item v-if="network?.results?.some(p=>p.profile?.length)" title="中心距与分离系数曲线" name="curves"><el-select v-model="selectedId" placeholder="选择井对"><el-option v-for="p in network?.results||[]" :key="p.neighbor_survey_version_id" :label="name(p)" :value="p.neighbor_survey_version_id"/></el-select><div ref="chart" class="curve-chart"/></el-collapse-item>
 <el-collapse-item title="风险井段" name="risks"><el-table :data="network?.risk_segments||[]" border max-height="250"><el-table-column prop="neighbor_well_id" label="邻井 ID"/><el-table-column prop="start_md" label="起点 MD（m）"/><el-table-column prop="end_md" label="终点 MD（m）"/><el-table-column label="等级"><template #default="s"><el-tag size="small" effect="plain" :style="riskStyle(s.row.risk_level)">{{riskName(s.row.risk_level)}}</el-tag></template></el-table-column><el-table-column prop="min_sf" label="最小 SF"/></el-table></el-collapse-item>
 <el-collapse-item v-if="network?.screened_pairs?.length" title="粗筛排除依据" name="screened"><el-table :data="network.screened_pairs" border><el-table-column label="邻井"><template #default="s">{{name(s.row)}}</template></el-table-column><el-table-column prop="lower_bound_distance" label="中心距保守下界（m）"/><el-table-column prop="risk_limit_distance" label="风险距离保守上界（m）"/></el-table></el-collapse-item>
 <el-collapse-item v-if="network?.failed_pairs?.length" title="未完成评价" name="failures"><el-table :data="network.failed_pairs"><el-table-column label="邻井"><template #default="s">{{name(s.row)}}</template></el-table-column><el-table-column prop="reason" label="原因"/></el-table></el-collapse-item>
 <el-collapse-item v-if="alarms.length" title="风险报警" name="alarms"><el-table :data="alarms"><el-table-column prop="message" label="报警"/><el-table-column prop="status" label="状态" width="130"/><el-table-column label="处理" width="120"><template #default="s"><el-button v-if="s.row.status==='OPEN'" link @click="$emit('acknowledge',s.row)">确认</el-button><el-button link @click="$emit('resolve',s.row)">解除</el-button></template></el-table-column></el-table></el-collapse-item></el-collapse></div>
</template>
<script setup>
import {useDisplayDictionary} from '@/views/operations/useDisplayDictionary'
const riskDictionary=useDisplayDictionary('risk_level')
import {ref,computed,watch,nextTick,onBeforeUnmount} from 'vue'
import {loadPlotly,chartPalette,plotConfig} from '@/utils/plotlyRuntime'
import {riskColors,riskLabels} from '@/utils/trajectoryColors'
const props=defineProps({network:Object,neighbors:{type:Array,default:()=>[]},alarms:{type:Array,default:()=>[]}})
defineEmits(['acknowledge','resolve']);const page=ref(1),limit=ref(10),selected=ref(),selectedId=ref(),chart=ref();let P,observer,disposed=false
const pairs=computed(()=>(props.network?.results||[]).slice((page.value-1)*limit.value,page.value*limit.value)),fmt=v=>v==null?'—':Number(v).toFixed(3),riskName=v=>riskDictionary.value.find(x=>x.dictValue===v)?.dictLabel || riskLabels[v]||({GREEN:'安全'}[v]||v||'—'),riskStyle=v=>({color:riskColors[v]||riskColors.BLUE,borderColor:riskColors[v]||riskColors.BLUE}),name=p=>{if(p.scope==='REFERENCE')return '正钻井眼';const n=props.neighbors.find(n=>n.survey_version_id===p.neighbor_survey_version_id);return n?`${n.well_code} / ${n.wellbore_name}`:`邻井 ${p.neighbor_well_id}`}
watch(()=>props.network,()=>{selectedId.value=props.network?.results?.[0]?.neighbor_survey_version_id;page.value=1},{immediate:true})
watch(selected,v=>{if(v)selectedId.value=v.neighbor_survey_version_id})
watch(selectedId,async()=>{await nextTick();const pair=props.network?.results?.find(p=>p.neighbor_survey_version_id===selectedId.value);if(!chart.value||!pair)return;P=await loadPlotly();if(disposed)return;const r=pair.profile||[],c=chartPalette();await P.react(chart.value,[{x:r.map(x=>x.md),y:r.map(x=>x.sf),name:'分离系数 SF',type:'scatter',mode:'lines',line:{color:'#075985'}},{x:r.map(x=>x.md),y:r.map(x=>x.center_distance),name:'中心距（m）',yaxis:'y2',type:'scatter',mode:'lines',line:{color:'#9a3412'}}],{paper_bgcolor:c.background,plot_bgcolor:c.background,font:{color:c.text,size:11},xaxis:{title:{text:'正钻井 MD（m）'}},yaxis:{title:{text:'SF'}},yaxis2:{title:{text:'中心距（m）'},overlaying:'y',side:'right'},legend:{orientation:'h'},margin:{l:55,r:60,t:30,b:50}},plotConfig);if(!observer){observer=new ResizeObserver(()=>P?.Plots.resize(chart.value));observer.observe(chart.value)}})
onBeforeUnmount(()=>{disposed=true;observer?.disconnect();if(P&&chart.value)P.purge(chart.value)})
</script>
<style scoped>.curve-chart{height:290px;min-width:0}.el-collapse{margin-top:12px}.el-select{max-width:100%}</style>
